//! The Rust column of the `typed-obligation/v0` conformance suite
//! (`fixtures/typed-obligation-v0/*.json`, generated by the predecessor
//! implementation and frozen; `verity_sp1.proofs.conformance` is the Python column).
//!
//! For every vector this test, from the `object` alone:
//!
//! 1. re-derives the canonical JSON bytes and the tagged digest;
//! 2. parses and validates the Verity-level object (subcircuits of one-output
//!    gates, boundaries of value references, obligations; IR §F) with an
//!    independent implementation of the interface's rules, in the order
//!    `verity_sp1.proofs.typed_obligation.validate` applies them, and compares
//!    verdict and code;
//! 3. for an accepted object, recomputes the lowering -- the legacy
//!    `KindProgram` bodies, slots and pins behind the lowering boundary -- and
//!    compares it with the vector's `lowering` record and `statement` bytes,
//!    parses those bytes with the crate's real `parse_statement`, resolves the
//!    gate set, and runs the crate's real `check_relations` on the vector's
//!    boundary values plus the sampled `Input` equations (the verdict must be
//!    the vector's `relations`);
//! 4. where the vector carries a witness -- format 1 (frame-v3 openings) or
//!    format 3 (whole packed leaves under the serving side's framing, read at
//!    statement-fixed word indices) -- runs the crate's real `check_any`
//!    (authentication + relations) on it and compares with the Python
//!    reference checker's verdict;
//! 5. the `binding` column (lane IB, IR §I.3): with `h_O` (step 1) and `h_L`
//!    (step 3) recomputed here, the correct prover's 65 public bytes
//!    `h_O || h_L || 1` are the vector's `public_values` and the crate's
//!    `check_binding` accepts them -- or, for a `binding/*` record carrying
//!    supplied public values, refuses them with the vector's `code`.
//!
//! Nothing here reaches into the guest beyond its public API; the validator
//! is test-side because the guest parses statements, not objects.

use std::collections::{BTreeMap, BTreeSet, HashMap};

use serde_json::Value as Json;
use veritor_zk_common::{
    bound_public_values, check_any, check_batch_ranged, check_binding, check_relations,
    expand_statement, gate_set, parse_any_witness, parse_leaf_descriptor, parse_packed_schema,
    parse_statement, parse_statement_v3, tagged_sha256, GateSet, PositionEntry, PositionRange,
    PositionRef, Statement, STATEMENT_MAGIC, STATEMENT_V3_MAGIC,
};

const DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../../fixtures/typed-obligation-v0");
const FORMAT: &str = "typed-obligation/v0";
const DIGEST_TAG: &[u8] = b"veritor/typed-obligation/v0";
const MERKLE_FRAMING: &str = "veritor/protocol/merkle/frame/v3";
const VLLM_FRAMING: &str = "verity-vllm/leaf/v1";

// --- canonical JSON (verity.ml.commitments.identity.canonical_json_text) --------------

fn canonical(value: &Json, out: &mut String) {
    match value {
        Json::Null => out.push_str("null"),
        Json::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Json::Number(n) => out.push_str(&n.to_string()),
        Json::String(s) => canonical_string(s, out),
        Json::Array(items) => {
            out.push('[');
            for (i, item) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                canonical(item, out);
            }
            out.push(']');
        }
        Json::Object(map) => {
            // sorted by key (code point order == UTF-8 byte order)
            let mut keys: Vec<&String> = map.keys().collect();
            keys.sort();
            out.push('{');
            for (i, key) in keys.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                canonical_string(key, out);
                out.push(':');
                canonical(&map[*key], out);
            }
            out.push('}');
        }
    }
}

/// Python `json.dumps(ensure_ascii=False)` escaping: `"`, `\`, the short
/// escapes for `\n \r \t \b \f`, `\u00XX` for other controls, everything else raw.
fn canonical_string(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{8}' => out.push_str("\\b"),
            '\u{c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
}

// --- the model -------------------------------------------------------------------------

#[derive(Clone, Debug, PartialEq, Eq)]
enum Type {
    /// `Value<w>`
    Bits(u32),
    /// `Array<n, T>`
    Array(Box<Type>, u64),
    /// `(T1, ..., Tk)`
    Tuple(Vec<Type>),
    /// a record (named product)
    Product(Vec<(String, Type)>),
    /// a type alias
    Named(String, Box<Type>),
}

#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
enum Selector {
    Index(u64),
    Field(String),
}

struct Root {
    id: String,
    owner: i128,
    domain: [u8; 32],
    root: [u8; 32],
    count: u64,
    framing: String,
}

/// A committed leaf: a commitment position and the layout of the words packed into it.
struct Leaf {
    id: String,
    root: String,
    leaf: u64,
    position: u64,
    layout: Type,
}

/// One canonical value reference (opaque to the guest) and where its word is committed.
struct Reference {
    id: String,
    leaf: String,
    offset: Vec<Selector>,
}

/// One gate of a subcircuit body: a primitive call (`op`, `args`) producing one
/// word, or a prescribed-input gate `Input` with its value as static data (IR §E).
struct Gate {
    op: String,
    /// `(is_gate, index)`: `["in", i]` the i-th incoming boundary value, `["gate", j]` an earlier gate
    args: Vec<(bool, u32)>,
    /// `Some((width, value))` for an `Input` gate
    input: Option<(u32, Vec<u8>)>,
}

/// A shared subcircuit body (IR §D.1): incoming widths, gates, outgoing gate indices.
struct Subcircuit {
    digest: [u8; 32],
    incoming: Vec<u32>,
    gates: Vec<Gate>,
    outgoing: Vec<u32>,
}

struct Obligation {
    session: [u8; 32],
    compiled: [u8; 32],
    unit: u64,
    replay_unit: u64,
    subcircuit: [u8; 32],
    roots: Vec<String>,
    /// graph boundary: distinct references, one per incoming width / outgoing gate
    boundary_in: Vec<String>,
    boundary_out: Vec<String>,
    /// declared call interface (ordered, may repeat), if any
    declared: Option<Declared>,
}

struct Declared {
    args: Vec<String>,
    returns: Vec<String>,
    /// the explicit partial map onto `boundary(S) = in ++ out` (memo decision 4):
    /// per occurrence the boundary index it is, or `None` for a non-boundary
    /// occurrence (a dead declared return); absent = the total map
    projection: Option<(Vec<Option<u32>>, Vec<Option<u32>>)>,
}

struct Object {
    family_id: String,
    family_digest: [u8; 32],
    width: u32,
    roots: Vec<Root>,
    leaves: Vec<Leaf>,
    references: Vec<Reference>,
    subcircuits: Vec<Subcircuit>,
    obligations: Vec<Obligation>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Code {
    Format,
    UnsupportedFamily,
    FamilyDigest,
    Order,
    SubcircuitConflict,
    UnknownFunction,
    Arity,
    DanglingReference,
    WidthMismatch,
    InputNotProtected,
    OutOfRangeOffset,
    IdentityConflict,
    BoundaryShape,
    DuplicateBoundaryValue,
    DuplicateProducer,
    NotLowerable,
}

impl Code {
    fn name(self) -> &'static str {
        match self {
            Code::Format => "E_FORMAT",
            Code::UnsupportedFamily => "E_UNSUPPORTED_FAMILY",
            Code::FamilyDigest => "E_FAMILY_DIGEST",
            Code::Order => "E_ORDER",
            Code::SubcircuitConflict => "E_SUBCIRCUIT_CONFLICT",
            Code::UnknownFunction => "E_UNKNOWN_FUNCTION",
            Code::Arity => "E_ARITY",
            Code::DanglingReference => "E_DANGLING_REFERENCE",
            Code::WidthMismatch => "E_WIDTH_MISMATCH",
            Code::InputNotProtected => "E_INPUT_NOT_PROTECTED",
            Code::OutOfRangeOffset => "E_OUT_OF_RANGE_OFFSET",
            Code::IdentityConflict => "E_IDENTITY_CONFLICT",
            Code::BoundaryShape => "E_BOUNDARY_SHAPE",
            Code::DuplicateBoundaryValue => "E_DUPLICATE_BOUNDARY_VALUE",
            Code::DuplicateProducer => "E_DUPLICATE_PRODUCER",
            Code::NotLowerable => "E_NOT_LOWERABLE",
        }
    }
}

type R<T> = Result<T, Code>;

// --- parsing (E_FORMAT) ------------------------------------------------------------------

fn ascii(v: &Json) -> R<String> {
    let s = v.as_str().ok_or(Code::Format)?;
    if s.is_empty() || !s.chars().all(|c| (0x20..=0x7e).contains(&(c as u32))) {
        return Err(Code::Format);
    }
    Ok(s.to_owned())
}

fn hex32(v: &Json) -> R<[u8; 32]> {
    let s = v.as_str().ok_or(Code::Format)?;
    if s.len() != 64 {
        return Err(Code::Format);
    }
    let bytes = hex(s)?;
    let mut out = [0u8; 32];
    out.copy_from_slice(&bytes);
    Ok(out)
}

fn hex(s: &str) -> R<Vec<u8>> {
    if s.len() % 2 != 0 || !s.chars().all(|c| matches!(c, '0'..='9' | 'a'..='f')) {
        return Err(Code::Format);
    }
    Ok((0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
        .collect())
}

fn uint(v: &Json, bound: u128) -> R<u64> {
    let n = v.as_u64().ok_or(Code::Format)?;
    if (n as u128) >= bound {
        return Err(Code::Format);
    }
    Ok(n)
}

fn field<'a>(obj: &'a Json, name: &str) -> R<&'a Json> {
    obj.get(name).ok_or(Code::Format)
}

fn object_with_keys<'a>(v: &'a Json, keys: &[&str]) -> R<&'a serde_json::Map<String, Json>> {
    let m = v.as_object().ok_or(Code::Format)?;
    if m.keys().any(|k| !keys.contains(&k.as_str())) {
        return Err(Code::Format);
    }
    Ok(m)
}

fn list_of_objects<'a>(v: &'a Json, name: &str, keys: &[&str]) -> R<Vec<&'a Json>> {
    let items = field(v, name)?.as_array().ok_or(Code::Format)?;
    for item in items {
        object_with_keys(item, keys)?;
    }
    Ok(items.iter().collect())
}

fn parse_type(v: &Json, table: &BTreeMap<String, Type>, depth: usize) -> R<Type> {
    if depth > 64 {
        return Err(Code::Format);
    }
    if let Some(name) = v.as_str() {
        return table.get(name).cloned().ok_or(Code::DanglingReference);
    }
    let m = v.as_object().ok_or(Code::Format)?;
    if m.len() != 1 {
        return Err(Code::Format);
    }
    let (constructor, body) = m.iter().next().unwrap();
    match constructor.as_str() {
        "value" => {
            let w = uint(body, 65)? as u32;
            if w == 0 {
                return Err(Code::Format);
            }
            Ok(Type::Bits(w))
        }
        "array" => {
            let pair = body.as_array().ok_or(Code::Format)?;
            if pair.len() != 2 {
                return Err(Code::Format);
            }
            let n = uint(&pair[0], 1 << 32)?;
            if n == 0 {
                return Err(Code::Format);
            }
            Ok(Type::Array(Box::new(parse_type(&pair[1], table, depth + 1)?), n))
        }
        "tuple" => {
            let items = body.as_array().ok_or(Code::Format)?;
            if items.is_empty() {
                return Err(Code::Format);
            }
            Ok(Type::Tuple(
                items
                    .iter()
                    .map(|t| parse_type(t, table, depth + 1))
                    .collect::<R<Vec<_>>>()?,
            ))
        }
        "record" => {
            let fields = body.as_array().ok_or(Code::Format)?;
            if fields.is_empty() {
                return Err(Code::Format);
            }
            let mut out = Vec::new();
            let mut names = BTreeSet::new();
            for f in fields {
                let pair = f.as_array().ok_or(Code::Format)?;
                if pair.len() != 2 {
                    return Err(Code::Format);
                }
                let name = ascii(&pair[0])?;
                if !names.insert(name.clone()) {
                    return Err(Code::Format);
                }
                out.push((name, parse_type(&pair[1], table, depth + 1)?));
            }
            Ok(Type::Product(out))
        }
        "named" => {
            let pair = body.as_array().ok_or(Code::Format)?;
            if pair.len() != 2 {
                return Err(Code::Format);
            }
            Ok(Type::Named(ascii(&pair[0])?, Box::new(parse_type(&pair[1], table, depth + 1)?)))
        }
        _ => Err(Code::Format),
    }
}

fn index_list(v: &Json, name: &str) -> R<Vec<u32>> {
    field(v, name)?
        .as_array()
        .ok_or(Code::Format)?
        .iter()
        .map(|x| uint(x, 1 << 32).map(|n| n as u32))
        .collect()
}

fn ref_list(v: &Json, name: &str) -> R<Vec<String>> {
    field(v, name)?.as_array().ok_or(Code::Format)?.iter().map(ascii).collect()
}

/// `projection.args` / `projection.returns`: boundary indices or `null`.
fn projection_list(v: &Json, name: &str) -> R<Vec<Option<u32>>> {
    field(v, name)?
        .as_array()
        .ok_or(Code::Format)?
        .iter()
        .map(|x| if x.is_null() { Ok(None) } else { uint(x, 1 << 32).map(|n| Some(n as u32)) })
        .collect()
}

fn parse_object(v: &Json) -> R<Object> {
    let top = v.as_object().ok_or(Code::Format)?;
    if top.get("format").and_then(Json::as_str) != Some(FORMAT) {
        return Err(Code::Format);
    }
    // Verity-level keys only: no `programs`, no `kind`, no slots (IR §F)
    const TOP: &[&str] =
        &["format", "family", "types", "roots", "leaves", "references", "subcircuits", "obligations"];
    if top.keys().any(|k| !TOP.contains(&k.as_str())) {
        return Err(Code::Format);
    }
    let fam = object_with_keys(field(v, "family")?, &["id", "digest", "width"])?;
    let family_id = ascii(fam.get("id").ok_or(Code::Format)?)?;
    let family_digest = hex32(fam.get("digest").ok_or(Code::Format)?)?;
    let width = uint(fam.get("width").ok_or(Code::Format)?, 1 << 32)? as u32;
    let mut table: BTreeMap<String, Type> = BTreeMap::new();
    if let Some(types) = top.get("types") {
        let types = types.as_object().ok_or(Code::Format)?;
        let mut names: Vec<&String> = types.keys().collect();
        names.sort();
        for name in names {
            ascii(&Json::String(name.clone()))?;
            let ty = parse_type(&types[name], &table, 0)?;
            table.insert(name.clone(), ty);
        }
    }
    let mut roots = Vec::new();
    for r in list_of_objects(v, "roots", &["id", "owner", "domain", "root", "count", "framing"])? {
        let owner = field(r, "owner")?.as_i64().ok_or(Code::Format)? as i128;
        if !(-2..(1i128 << 64) - 2).contains(&owner) {
            return Err(Code::Format);
        }
        let framing = match r.get("framing") {
            None => MERKLE_FRAMING.to_owned(),
            Some(f) => {
                let f = f.as_str().ok_or(Code::Format)?;
                if f != MERKLE_FRAMING && f != VLLM_FRAMING {
                    return Err(Code::Format);
                }
                f.to_owned()
            }
        };
        roots.push(Root {
            id: ascii(field(r, "id")?)?,
            owner,
            domain: hex32(field(r, "domain")?)?,
            root: hex32(field(r, "root")?)?,
            count: uint(field(r, "count")?, 1 << 64)?,
            framing,
        });
    }
    let mut leaves = Vec::new();
    for val in list_of_objects(v, "leaves", &["id", "root", "leaf", "position", "layout"])? {
        leaves.push(Leaf {
            id: ascii(field(val, "id")?)?,
            root: ascii(field(val, "root")?)?,
            leaf: uint(field(val, "leaf")?, 1 << 64)?,
            position: uint(field(val, "position")?, 1 << 64)?,
            layout: parse_type(field(val, "layout")?, &table, 0)?,
        });
    }
    let mut references = Vec::new();
    for r in list_of_objects(v, "references", &["ref", "leaf", "offset"])? {
        let mut offset = Vec::new();
        for s in field(r, "offset")?.as_array().ok_or(Code::Format)? {
            offset.push(match s {
                Json::Number(_) => Selector::Index(uint(s, 1 << 32)?),
                Json::String(_) => Selector::Field(ascii(s)?),
                _ => return Err(Code::Format),
            });
        }
        references.push(Reference {
            id: ascii(field(r, "ref")?)?,
            leaf: ascii(field(r, "leaf")?)?,
            offset,
        });
    }
    let mut subcircuits = Vec::new();
    for s in list_of_objects(v, "subcircuits", &["digest", "in", "gates", "out", "definition"])? {
        let mut gates = Vec::new();
        for g in field(s, "gates")?.as_array().ok_or(Code::Format)? {
            let op = ascii(field(g, "op")?)?;
            if op == "Input" {
                object_with_keys(g, &["op", "width", "value"])?;
                let width = uint(field(g, "width")?, 65)? as u32;
                let value = hex(field(g, "value")?.as_str().ok_or(Code::Format)?)?;
                if value.is_empty() {
                    return Err(Code::Format);
                }
                gates.push(Gate { op, args: Vec::new(), input: Some((width, value)) });
                continue;
            }
            object_with_keys(g, &["op", "args"])?;
            let mut args = Vec::new();
            for arg in field(g, "args")?.as_array().ok_or(Code::Format)? {
                let pair = arg.as_array().ok_or(Code::Format)?;
                if pair.len() != 2 {
                    return Err(Code::Format);
                }
                let space = match pair[0].as_str() {
                    Some("in") => false,
                    Some("gate") => true,
                    _ => return Err(Code::Format),
                };
                args.push((space, uint(&pair[1], 1 << 32)? as u32));
            }
            gates.push(Gate { op, args, input: None });
        }
        if let Some(d) = s.get("definition") {
            let d = object_with_keys(d, &["name", "static", "within"])?;
            ascii(d.get("name").ok_or(Code::Format)?)?;
            if let Some(statics) = d.get("static") {
                for (key, value) in statics.as_object().ok_or(Code::Format)? {
                    ascii(&Json::String(key.clone()))?;
                    match value {
                        Json::String(_) => ascii(value)?,
                        Json::Number(_) => uint(value, 1 << 64)?.to_string(),
                        _ => return Err(Code::Format),
                    };
                }
            }
            if let Some(within) = d.get("within") {
                ascii(within)?;
            }
        }
        subcircuits.push(Subcircuit {
            digest: hex32(field(s, "digest")?)?,
            incoming: index_list(s, "in")?,
            gates,
            outgoing: index_list(s, "out")?,
        });
    }
    let mut obligations = Vec::new();
    for o in list_of_objects(
        v,
        "obligations",
        &["binding", "subcircuit", "roots", "boundary", "declared_interface", "target"],
    )? {
        let b = object_with_keys(field(o, "binding")?, &["session", "compiled", "unit", "replay_unit"])?;
        let boundary = field(o, "boundary")?;
        object_with_keys(boundary, &["in", "out"])?;
        let declared = match o.get("declared_interface") {
            None => None,
            Some(di) => {
                object_with_keys(di, &["args", "returns", "projection"])?;
                let projection = match di.get("projection") {
                    None => None,
                    Some(p) => {
                        object_with_keys(p, &["args", "returns"])?;
                        Some((projection_list(p, "args")?, projection_list(p, "returns")?))
                    }
                };
                Some(Declared { args: ref_list(di, "args")?, returns: ref_list(di, "returns")?, projection })
            }
        };
        if let Some(t) = o.get("target") {
            // the target's encoding: a region (contiguous) or a function-call
            // instance; noncontiguous encodings are a later item (IR §D.1)
            object_with_keys(t, &["encoding", "id"])?;
            let encoding = ascii(field(t, "encoding")?)?;
            if encoding != "region" && encoding != "call" {
                return Err(Code::Format);
            }
            ascii(field(t, "id")?)?;
        }
        obligations.push(Obligation {
            session: hex32(b.get("session").ok_or(Code::Format)?)?,
            compiled: hex32(b.get("compiled").ok_or(Code::Format)?)?,
            unit: uint(b.get("unit").ok_or(Code::Format)?, 1 << 64)?,
            replay_unit: uint(b.get("replay_unit").ok_or(Code::Format)?, 1 << 64)?,
            subcircuit: hex32(field(o, "subcircuit")?)?,
            roots: ref_list(o, "roots")?,
            boundary_in: ref_list(boundary, "in")?,
            boundary_out: ref_list(boundary, "out")?,
            declared,
        });
    }
    Ok(Object { family_id, family_digest, width, roots, leaves, references, subcircuits, obligations })
}

// --- validation (the rules of typed-obligation-v0.md §11, in order) ------------------------

const SUPPORTED: &[&str] = &[
    "veritor.toy-isa@1",
    "veritor.word-arithmetic@2",
    "veritor.int8-q7@1",
    "veritor.tensor-core.ampere_bf16_m16n8k16@2",
    "veritor.tc-ampere-bf16@1",
    "veritor.tc-ampere-bf16@2",
];

const SUBCIRCUIT_TAG: &[u8] = b"veritor/typed-obligation/v0/subcircuit";

fn scalar_width(mut t: &Type) -> Option<u32> {
    loop {
        match t {
            Type::Named(_, of) => t = of,
            Type::Bits(w) => return Some(*w),
            _ => return None,
        }
    }
}

fn component<'a>(mut t: &'a Type, path: &[Selector]) -> R<&'a Type> {
    for step in path {
        while let Type::Named(_, of) = t {
            t = of;
        }
        match (t, step) {
            (Type::Array(of, n), Selector::Index(i)) if i < n => t = of,
            (Type::Tuple(items), Selector::Index(i)) if (*i as usize) < items.len() => {
                t = &items[*i as usize]
            }
            (Type::Product(fields), Selector::Field(name)) => {
                t = &fields
                    .iter()
                    .find(|(n, _)| n == name)
                    .ok_or(Code::OutOfRangeOffset)?
                    .1;
            }
            _ => return Err(Code::OutOfRangeOffset),
        }
    }
    Ok(t)
}

fn is_sorted_distinct<T: Ord>(items: &[T]) -> bool {
    items.windows(2).all(|w| w[0] < w[1])
}

/// The subcircuit's identity: the tagged digest of its canonical body JSON.
fn subcircuit_digest(s: &Subcircuit) -> [u8; 32] {
    let gates: Vec<Json> = s
        .gates
        .iter()
        .map(|g| match &g.input {
            Some((w, v)) => serde_json::json!({"op": "Input", "width": w, "value": hex_string(v)}),
            None => serde_json::json!({
                "op": g.op,
                "args": g.args.iter().map(|&(is_gate, i)| serde_json::json!([if is_gate { "gate" } else { "in" }, i])).collect::<Vec<_>>(),
            }),
        })
        .collect();
    let body = serde_json::json!({"in": s.incoming, "gates": gates, "out": s.outgoing});
    let mut text = String::new();
    canonical(&body, &mut text);
    tagged_sha256(SUBCIRCUIT_TAG, text.as_bytes())
}

fn gate_width(g: &Gate, set: &GateSet) -> u32 {
    match &g.input {
        Some((w, _)) => *w,
        None => set.op_width(set.op(&g.op).expect("validated")),
    }
}

fn validate(obj: &Object) -> R<GateSet> {
    if !SUPPORTED.contains(&obj.family_id.as_str()) {
        return Err(Code::UnsupportedFamily);
    }
    let set = GateSet::resolve(&obj.family_id, obj.width).ok_or(Code::FamilyDigest)?;
    if set.digest() != obj.family_digest {
        return Err(Code::FamilyDigest);
    }
    // roots
    let root_ids: Vec<&String> = obj.roots.iter().map(|r| &r.id).collect();
    if !is_sorted_distinct(&root_ids) {
        return Err(Code::Order);
    }
    let roots: HashMap<&str, &Root> = obj.roots.iter().map(|r| (r.id.as_str(), r)).collect();
    // leaves (commitment positions)
    let leaf_ids: Vec<&String> = obj.leaves.iter().map(|v| &v.id).collect();
    if !is_sorted_distinct(&leaf_ids) {
        return Err(Code::Order);
    }
    let mut ranks = BTreeSet::new();
    let mut positions = BTreeSet::new();
    for v in &obj.leaves {
        let root = roots.get(v.root.as_str()).ok_or(Code::DanglingReference)?;
        if v.leaf >= root.count {
            return Err(Code::OutOfRangeOffset);
        }
        if !ranks.insert((&v.root, v.leaf)) {
            return Err(Code::IdentityConflict);
        }
        if !positions.insert((&v.root, v.position)) {
            return Err(Code::IdentityConflict);
        }
    }
    let leaves: HashMap<&str, &Leaf> = obj.leaves.iter().map(|v| (v.id.as_str(), v)).collect();
    // references (canonical value references and where each word is committed)
    let ref_ids: Vec<&String> = obj.references.iter().map(|r| &r.id).collect();
    if !is_sorted_distinct(&ref_ids) {
        return Err(Code::Order);
    }
    let mut committed_at: BTreeSet<(&String, &Vec<Selector>)> = BTreeSet::new();
    let mut ref_width: HashMap<&str, u32> = HashMap::new();
    for r in &obj.references {
        let leaf = leaves.get(r.leaf.as_str()).ok_or(Code::DanglingReference)?;
        let width = scalar_width(component(&leaf.layout, &r.offset)?).ok_or(Code::OutOfRangeOffset)?;
        if !committed_at.insert((&r.leaf, &r.offset)) {
            return Err(Code::IdentityConflict);
        }
        ref_width.insert(r.id.as_str(), width);
    }
    let references: HashMap<&str, &Reference> = obj.references.iter().map(|r| (r.id.as_str(), r)).collect();
    // subcircuits
    let digests: Vec<[u8; 32]> = obj.subcircuits.iter().map(|s| s.digest).collect();
    if digests.iter().collect::<BTreeSet<_>>().len() != digests.len() {
        return Err(Code::SubcircuitConflict);
    }
    if !is_sorted_distinct(&digests) {
        return Err(Code::Order);
    }
    for s in &obj.subcircuits {
        if subcircuit_digest(s) != s.digest {
            return Err(Code::SubcircuitConflict);
        }
        validate_subcircuit(s, &set)?;
    }
    let subcircuits: HashMap<[u8; 32], &Subcircuit> = obj.subcircuits.iter().map(|s| (s.digest, s)).collect();
    // obligations
    let keys: Vec<([u8; 32], [u8; 32], u64)> =
        obj.obligations.iter().map(|o| (o.session, o.compiled, o.unit)).collect();
    if !is_sorted_distinct(&keys) {
        return Err(Code::Order);
    }
    let mut producers: BTreeSet<&String> = BTreeSet::new();
    for o in &obj.obligations {
        let s = subcircuits.get(&o.subcircuit).ok_or(Code::DanglingReference)?;
        if o.roots.iter().collect::<BTreeSet<_>>().len() != o.roots.len() {
            return Err(Code::Order);
        }
        for rid in &o.roots {
            if !roots.contains_key(rid.as_str()) {
                return Err(Code::DanglingReference);
            }
        }
        if o.boundary_in.len() != s.incoming.len() || o.boundary_out.len() != s.outgoing.len() {
            return Err(Code::BoundaryShape);
        }
        let mut seen = BTreeSet::new();
        for rid in o.boundary_in.iter().chain(&o.boundary_out) {
            let r = references.get(rid.as_str()).ok_or(Code::DanglingReference)?;
            if !o.roots.contains(&leaves[r.leaf.as_str()].root) {
                return Err(Code::DanglingReference);
            }
            if !seen.insert(rid) {
                return Err(Code::DuplicateBoundaryValue);
            }
        }
        for (i, rid) in o.boundary_in.iter().enumerate() {
            if ref_width[rid.as_str()] != s.incoming[i] {
                return Err(Code::WidthMismatch);
            }
        }
        for (m, rid) in o.boundary_out.iter().enumerate() {
            if ref_width[rid.as_str()] != gate_width(&s.gates[s.outgoing[m] as usize], &set) {
                return Err(Code::WidthMismatch);
            }
        }
        if let Some(di) = &o.declared {
            validate_declared(o, di, &seen)?;
        }
        for rid in &o.boundary_out {
            if !producers.insert(rid) {
                return Err(Code::DuplicateProducer);
            }
        }
    }
    // lowerability: the legacy backend pins only positions of its source width
    let source_width = set.op_width(set.op("in").expect("every family has `in`"));
    for s in &obj.subcircuits {
        for g in &s.gates {
            if let Some((w, _)) = &g.input {
                if *w != source_width {
                    return Err(Code::NotLowerable);
                }
            }
        }
    }
    Ok(set)
}

/// The declared interface projects onto `boundary(S) = in ++ out` (§7): without
/// `projection` the total map (every declared reference on the boundary, the
/// distinct args exactly the incoming boundary); with `projection` the explicit
/// partial map (an index names the entry the occurrence *is*; `null` marks a
/// non-boundary occurrence; the mapped args are exactly the incoming entries).
fn validate_declared(o: &Obligation, di: &Declared, on_boundary: &BTreeSet<&String>) -> R<()> {
    let Some((p_args, p_returns)) = &di.projection else {
        for rid in di.args.iter().chain(&di.returns) {
            if !on_boundary.contains(rid) {
                return Err(Code::DanglingReference);
            }
        }
        let distinct_args: BTreeSet<&String> = di.args.iter().collect();
        let incoming: BTreeSet<&String> = o.boundary_in.iter().collect();
        if distinct_args != incoming {
            return Err(Code::BoundaryShape);
        }
        return Ok(());
    };
    if p_args.len() != di.args.len() || p_returns.len() != di.returns.len() {
        return Err(Code::Format);
    }
    let boundary: Vec<&String> = o.boundary_in.iter().chain(&o.boundary_out).collect();
    for (refs, indices) in [(&di.args, p_args), (&di.returns, p_returns)] {
        for (rid, target) in refs.iter().zip(indices) {
            match target {
                None => {
                    if on_boundary.contains(rid) {
                        return Err(Code::BoundaryShape);
                    }
                }
                Some(t) => {
                    let entry = boundary.get(*t as usize).ok_or(Code::DanglingReference)?;
                    if *entry != rid {
                        return Err(Code::BoundaryShape);
                    }
                }
            }
        }
    }
    let mapped: BTreeSet<u32> = p_args.iter().flatten().copied().collect();
    let incoming: BTreeSet<u32> = (0..o.boundary_in.len() as u32).collect();
    if mapped != incoming {
        return Err(Code::BoundaryShape);
    }
    Ok(())
}

fn validate_subcircuit(s: &Subcircuit, set: &GateSet) -> R<()> {
    if s.incoming.iter().any(|w| !(1..=64).contains(w)) {
        return Err(Code::Format);
    }
    let outgoing: BTreeSet<u32> = s.outgoing.iter().copied().collect();
    let mut produced: Vec<u32> = Vec::new();
    for (j, gate) in s.gates.iter().enumerate() {
        if let Some((w, value)) = &gate.input {
            if !(1..=64).contains(w) {
                return Err(Code::Format);
            }
            let bytes = ((*w + 7) / 8) as usize;
            let fits = value.len() == bytes && (w % 8 == 0 || (value[0] as u32) < (1 << (w % 8)));
            if !fits {
                return Err(Code::WidthMismatch);
            }
            if !outgoing.contains(&(j as u32)) {
                return Err(Code::InputNotProtected);
            }
            produced.push(*w);
            continue;
        }
        if gate.op == "in" || gate.op == "weight" {
            // a backend source is a lowering, not a gate
            return Err(Code::UnknownFunction);
        }
        let op = set.op(&gate.op).ok_or(Code::UnknownFunction)?;
        if gate.args.len() != op.arity() {
            return Err(Code::Arity);
        }
        for (i, &(is_gate, index)) in gate.args.iter().enumerate() {
            let width = if is_gate {
                if index as usize >= j {
                    return Err(Code::DanglingReference);
                }
                produced[index as usize]
            } else {
                if index as usize >= s.incoming.len() {
                    return Err(Code::DanglingReference);
                }
                s.incoming[index as usize]
            };
            if width != set.arg_width(op, i) {
                return Err(Code::WidthMismatch);
            }
        }
        produced.push(set.op_width(op));
    }
    if !is_sorted_distinct(&s.outgoing) {
        return Err(Code::Order);
    }
    if s.outgoing.iter().any(|&o| o as usize >= s.gates.len()) {
        return Err(Code::DanglingReference);
    }
    Ok(())
}

// --- the lowering boundary (verity_sp1.proofs.lowering.lower) -----------------------------------
//
// Below this line is the legacy backend's representation: `KindProgram` bodies
// (ports, `port k` / `local i`, opened offsets), obligation slots, `PositionRef`
// pins.  It is a function of the Verity-level object: incoming value i -> port
// i; gate j -> local j; an `Input` gate -> the family's `in` source gate, opened,
// its position pinned to the prescribed value; positions = boundary.in ++
// boundary.out.  The vector's `lowering` record and `statement` bytes are what
// this must reproduce.

const LEGACY_PROGRAM_TAG: &[u8] = b"veritor/typed-obligation/v0/program";

#[derive(Default)]
struct Writer(Vec<u8>);

impl Writer {
    fn raw(&mut self, b: &[u8]) {
        self.0.extend_from_slice(b);
    }
    fn u8(&mut self, v: u8) {
        self.0.push(v);
    }
    fn u32(&mut self, v: u32) {
        self.0.extend_from_slice(&v.to_be_bytes());
    }
    fn u64(&mut self, v: u64) {
        self.0.extend_from_slice(&v.to_be_bytes());
    }
    fn bytes(&mut self, b: &[u8]) {
        self.u32(b.len() as u32);
        self.0.extend_from_slice(b);
    }
}

struct LegacyProgram {
    kind: [u8; 32],
    ports: Vec<u32>,
    gates: Vec<(String, Vec<(bool, u32)>)>,
    outputs: Vec<u32>,
    description: Json,
}

fn lower_subcircuit(s: &Subcircuit) -> LegacyProgram {
    let gates: Vec<(String, Vec<(bool, u32)>)> = s
        .gates
        .iter()
        .map(|g| match &g.input {
            Some(_) => ("in".to_owned(), Vec::new()),
            None => (g.op.clone(), g.args.clone()),
        })
        .collect();
    let body = serde_json::json!({
        "ports": s.incoming.iter().enumerate().map(|(i, w)| serde_json::json!({"ordinal": i, "width": w})).collect::<Vec<_>>(),
        "gates": gates.iter().map(|(op, args)| serde_json::json!({
            "op": op,
            "args": args.iter().map(|&(local, i)| serde_json::json!([if local { "local" } else { "port" }, i])).collect::<Vec<_>>(),
        })).collect::<Vec<_>>(),
        "outputs": s.outgoing,
    });
    let mut text = String::new();
    canonical(&body, &mut text);
    let kind = tagged_sha256(LEGACY_PROGRAM_TAG, text.as_bytes());
    let mut description = body.clone();
    description["subcircuit"] = Json::String(hex_string(&s.digest));
    description["kind"] = Json::String(hex_string(&kind));
    LegacyProgram { kind, ports: s.incoming.clone(), gates, outputs: s.outgoing.clone(), description }
}

/// `lower()`: the statement bytes and the JSON description of the backend data.
/// `(w, extents)` if the layout is `Array<n1, ... Array<nk, Value<w>>>` through aliases
/// (a uniform packing of one word type, row-major); `None` for tuples and records.
fn uniform_packing(mut t: &Type) -> Option<(u32, Vec<u64>)> {
    let mut extents = Vec::new();
    loop {
        match t {
            Type::Named(_, of) => t = of,
            Type::Bits(w) => return Some((*w, extents)),
            Type::Array(of, n) => {
                extents.push(*n);
                t = of;
            }
            _ => return None,
        }
    }
}

/// The checked `ValueRef -> CommitmentPosition` mapping
/// (`verity_sp1.proofs.lowering.commitment_position`): the leaf schema of one
/// reference.  `u<w>` for a one-word leaf under frame v3 (and for every leaf
/// the guest cannot open one word of); under `verity-vllm/leaf/v1` a uniformly
/// packed leaf gives `packed/v1:verity-vllm/leaf/v1:u<w>le:<count>:<index>`
/// with the word's row-major index -- the serving side commits raw
/// little-endian words.
fn position_schema(root: &Root, leaf: &Leaf, offset: &[Selector]) -> String {
    let width = scalar_width(component(&leaf.layout, offset).unwrap()).unwrap();
    if root.framing == VLLM_FRAMING {
        if let Some((w, extents)) = uniform_packing(&leaf.layout) {
            assert_eq!(w, width);
            let count: u64 = extents.iter().product();
            let mut index = 0u64;
            for (extent, step) in extents.iter().zip(offset) {
                let Selector::Index(i) = step else { unreachable!() };
                index = index * extent + i;
            }
            return format!("packed/v1:{VLLM_FRAMING}:u{width}le:{count}:{index}");
        }
    }
    format!("u{width}")
}

fn lower(obj: &Object) -> (Vec<u8>, Json) {
    let roots: HashMap<&str, &Root> = obj.roots.iter().map(|r| (r.id.as_str(), r)).collect();
    let leaves: HashMap<&str, &Leaf> = obj.leaves.iter().map(|v| (v.id.as_str(), v)).collect();
    let references: HashMap<&str, &Reference> = obj.references.iter().map(|r| (r.id.as_str(), r)).collect();
    let subcircuits: HashMap<[u8; 32], &Subcircuit> = obj.subcircuits.iter().map(|s| (s.digest, s)).collect();
    let lowered: HashMap<[u8; 32], LegacyProgram> =
        obj.subcircuits.iter().map(|s| (s.digest, lower_subcircuit(s))).collect();
    // one legacy body per distinct kind (bodies differing only in Input values share one)
    let mut kinds: BTreeMap<[u8; 32], &LegacyProgram> = BTreeMap::new();
    for p in lowered.values() {
        kinds.entry(p.kind).or_insert(p);
    }
    let mut w = Writer::default();
    w.raw(STATEMENT_MAGIC);
    w.bytes(obj.family_id.as_bytes());
    w.raw(&obj.family_digest);
    w.u32(obj.width);
    w.u32(kinds.len() as u32);
    for p in kinds.values() {
        w.raw(&p.kind);
        w.u32(p.gates.len() as u32);
        w.u32(p.ports.len() as u32);
        for k in 0..p.ports.len() {
            w.u32(k as u32);
        }
        w.u32(p.gates.len() as u32);
        for (op, args) in &p.gates {
            w.bytes(op.as_bytes());
            w.u32(args.len() as u32);
            for &(local, index) in args {
                w.u8(local as u8);
                w.u32(index);
            }
        }
        w.u32(p.outputs.len() as u32);
        for &o in &p.outputs {
            w.u32(o);
        }
    }
    let mut descriptions = Vec::new();
    w.u32(obj.obligations.len() as u32);
    for o in &obj.obligations {
        let s = subcircuits[&o.subcircuit];
        let p = &lowered[&o.subcircuit];
        w.raw(&o.session);
        w.raw(&o.compiled);
        w.u64(o.unit);
        w.u64(o.replay_unit);
        w.raw(&p.kind);
        w.u32(o.roots.len() as u32);
        for rid in &o.roots {
            let r = roots[rid.as_str()];
            w.u64((r.owner + 2) as u64);
            w.raw(&r.domain);
            w.raw(&r.root);
            w.u64(r.count);
        }
        // the sampled Input equations: a pin on the position of each Input gate's value
        let mut pins: BTreeMap<&str, &Vec<u8>> = BTreeMap::new();
        for (m, rid) in o.boundary_out.iter().enumerate() {
            if let Some((_, value)) = &s.gates[s.outgoing[m] as usize].input {
                pins.insert(rid.as_str(), value);
            }
        }
        let ordered: Vec<&String> = o.boundary_in.iter().chain(&o.boundary_out).collect();
        w.u32(ordered.len() as u32);
        for rid in &ordered {
            let r = references[rid.as_str()];
            let v = leaves[r.leaf.as_str()];
            w.u32(o.roots.iter().position(|x| *x == v.root).unwrap() as u32);
            w.u64(v.leaf);
            w.u64(v.position);
            w.bytes(position_schema(roots[v.root.as_str()], v, &r.offset).as_bytes());
            match pins.get(rid.as_str()) {
                None => w.u8(0),
                Some(e) => {
                    w.u8(1);
                    w.bytes(e);
                }
            }
        }
        let n_in = o.boundary_in.len() as u32;
        let inputs: Vec<u32> = (0..n_in).collect();
        let outputs: Vec<u32> = (0..o.boundary_out.len() as u32).map(|m| n_in + m).collect();
        w.u32(inputs.len() as u32);
        for &x in &inputs {
            w.u32(x);
        }
        w.u32(outputs.len() as u32);
        for &x in &outputs {
            w.u32(x);
        }
        descriptions.push(serde_json::json!({
            "kind": hex_string(&p.kind),
            "positions": ordered,
            "inputs": inputs,
            "outputs": outputs,
            "expected": pins.iter().map(|(k, v)| (k.to_string(), Json::String(hex_string(v)))).collect::<serde_json::Map<_, _>>(),
        }));
    }
    let mut programs: Vec<&LegacyProgram> = lowered.values().collect();
    programs.sort_by_key(|p| (p.kind, p.description["subcircuit"].as_str().unwrap().to_owned()));
    let description = serde_json::json!({
        "note": "derived by veritor.interface.lowering.lower(); legacy backend data, not part of the Verity ontology",
        "programs": programs.iter().map(|p| p.description.clone()).collect::<Vec<_>>(),
        "obligations": descriptions,
    });
    (w.0, description)
}


/// `verity_sp1.proofs.lowering.merge_ranges`: maximal runs of `>= 2` consecutive
/// unpinned packed positions of one leaf (same commitment, rank, position and
/// descriptor) whose indices advance by one constant positive stride become one
/// range; everything else stays a single.  The format-3 lowering of a position list.
fn merge_ranges(positions: &[PositionRef]) -> Vec<PositionEntry> {
    let mut entries = Vec::new();
    let mut i = 0;
    while i < positions.len() {
        let head = &positions[i];
        let parsed = if head.expected.is_some() { None } else { parse_packed_schema(&head.schema) };
        let Some(parsed) = parsed else {
            entries.push(PositionEntry::Single(head.clone()));
            i += 1;
            continue;
        };
        let descriptor = parsed.descriptor();
        let mut indices = vec![parsed.index];
        let mut stride: Option<u64> = None;
        let mut j = i + 1;
        while j < positions.len() {
            let candidate = &positions[j];
            if candidate.expected.is_some() {
                break;
            }
            let Some(packed) = parse_packed_schema(&candidate.schema) else { break };
            if (candidate.commitment, candidate.rank, candidate.position, packed.descriptor())
                != (head.commitment, head.rank, head.position, descriptor)
            {
                break;
            }
            let last = *indices.last().unwrap();
            if packed.index <= last {
                break;
            }
            let step = packed.index - last;
            if stride.is_some_and(|s| s != step) {
                break;
            }
            stride = Some(step);
            indices.push(packed.index);
            j += 1;
        }
        if indices.len() >= 2 {
            let order = if descriptor.little_endian { "le" } else { "be" };
            entries.push(PositionEntry::Range(PositionRange {
                commitment: head.commitment,
                rank: head.rank,
                position: head.position,
                descriptor: format!("packed/v1:{}:u{}{order}:{}", descriptor.framing, descriptor.width, descriptor.count),
                start: indices[0],
                count: indices.len() as u64,
                stride: stride.unwrap(),
            }));
            i = j;
        } else {
            entries.push(PositionEntry::Single(head.clone()));
            i += 1;
        }
    }
    entries
}

/// `wire.encode_statement_v3`: the format-3 bytes of a statement with tagged entries.
fn encode_v3(statement: &Statement<PositionEntry>) -> Vec<u8> {
    let mut w = Writer::default();
    w.raw(STATEMENT_V3_MAGIC);
    w.bytes(statement.gate_set_id.as_bytes());
    w.raw(&statement.gate_set_digest);
    w.u32(statement.width);
    w.u32(statement.kinds.len() as u32);
    for p in &statement.kinds {
        w.raw(&p.kind);
        w.u32(p.size);
        w.u32(p.ports.len() as u32);
        for &k in &p.ports {
            w.u32(k);
        }
        w.u32(p.gates.len() as u32);
        for gate in &p.gates {
            w.bytes(gate.op.as_bytes());
            w.u32(gate.args.len() as u32);
            for arg in &gate.args {
                match arg {
                    veritor_zk_common::Arg::Port(k) => {
                        w.u8(0);
                        w.u32(*k);
                    }
                    veritor_zk_common::Arg::Local(j) => {
                        w.u8(1);
                        w.u32(*j);
                    }
                }
            }
        }
        w.u32(p.outputs.len() as u32);
        for &o in &p.outputs {
            w.u32(o);
        }
    }
    w.u32(statement.obligations.len() as u32);
    for o in &statement.obligations {
        w.raw(&o.session);
        w.raw(&o.compiled);
        w.u64(o.unit);
        w.u64(o.replay_unit);
        w.raw(&o.kind);
        w.u32(o.commitments.len() as u32);
        for c in &o.commitments {
            w.u64(c.owner_plus_two);
            w.raw(&c.domain_id);
            w.raw(&c.root);
            w.u64(c.count);
        }
        w.u32(o.positions.len() as u32);
        for entry in &o.positions {
            match entry {
                PositionEntry::Single(p) => {
                    w.u8(0);
                    w.u32(p.commitment);
                    w.u64(p.rank);
                    w.u64(p.position);
                    w.bytes(p.schema.as_bytes());
                    match &p.expected {
                        None => w.u8(0),
                        Some(e) => {
                            w.u8(1);
                            w.bytes(e);
                        }
                    }
                }
                PositionEntry::Range(r) => {
                    w.u8(1);
                    w.u32(r.commitment);
                    w.u64(r.rank);
                    w.u64(r.position);
                    w.bytes(r.descriptor.as_bytes());
                    w.u64(r.start);
                    w.u64(r.count);
                    w.u64(r.stride);
                }
            }
        }
        w.u32(o.inputs.len() as u32);
        for &x in &o.inputs {
            w.u32(x);
        }
        w.u32(o.outputs.len() as u32);
        for &x in &o.outputs {
            w.u32(x);
        }
    }
    w.0
}

/// `verity_sp1.proofs.lowering.lower_v3`: the format-2 lowering with its position
/// lists merged into ranges, as bytes and as the `lowered_v3` description.
fn lower_v3(statement: &Statement, description: &Json) -> (Vec<u8>, Statement<PositionEntry>, Json) {
    let mut obligations = Vec::new();
    let mut descriptions = Vec::new();
    for (o, d) in statement.obligations.iter().zip(description["obligations"].as_array().unwrap()) {
        let entries = merge_ranges(&o.positions);
        let refs = d["positions"].as_array().unwrap();
        let mut listed = Vec::new();
        let mut offset = 0usize;
        for entry in &entries {
            match entry {
                PositionEntry::Range(r) => {
                    let count = r.count as usize;
                    listed.push(serde_json::json!({
                        "refs": [refs[offset], refs[offset + count - 1]],
                        "commitment": r.commitment,
                        "rank": r.rank,
                        "position": r.position,
                        "descriptor": r.descriptor,
                        "start": r.start,
                        "count": r.count,
                        "stride": r.stride,
                        "first_schema": o.positions[offset].schema,
                        "last_schema": o.positions[offset + count - 1].schema,
                    }));
                    offset += count;
                }
                PositionEntry::Single(p) => {
                    listed.push(serde_json::json!({"ref": refs[offset], "schema": p.schema}));
                    offset += 1;
                }
            }
        }
        assert_eq!(offset, o.positions.len());
        descriptions.push(serde_json::json!({
            "kind": d["kind"],
            "entries": listed,
            "ranges": entries.iter().filter(|e| matches!(e, PositionEntry::Range(_))).count(),
            "slots": o.positions.len(),
            "inputs": d["inputs"],
            "outputs": d["outputs"],
            "expected": d["expected"],
        }));
        obligations.push(veritor_zk_common::Obligation {
            session: o.session,
            compiled: o.compiled,
            unit: o.unit,
            replay_unit: o.replay_unit,
            kind: o.kind,
            commitments: o.commitments.clone(),
            positions: entries,
            inputs: o.inputs.clone(),
            outputs: o.outputs.clone(),
        });
    }
    let v3 = Statement {
        gate_set_id: statement.gate_set_id.clone(),
        gate_set_digest: statement.gate_set_digest,
        width: statement.width,
        kinds: statement.kinds.clone(),
        obligations,
    };
    let described = serde_json::json!({
        "note": "derived by veritor.interface.lowering.lower_v3(): the format-2 lowering with maximal runs of consecutive packed words of one leaf merged into ranges (merge_ranges); expands to `lowering`",
        "programs": description["programs"],
        "obligations": descriptions,
    });
    (encode_v3(&v3), v3, described)
}

/// `veritor.interface.lowering.authenticity`: every boundary word is either a
/// one-word leaf under frame v3 or a word of a uniformly packed leaf under the
/// serving side's framing.
fn authenticatable(obj: &Object) -> bool {
    let roots: HashMap<&str, &Root> = obj.roots.iter().map(|r| (r.id.as_str(), r)).collect();
    let leaves: HashMap<&str, &Leaf> = obj.leaves.iter().map(|v| (v.id.as_str(), v)).collect();
    let references: HashMap<&str, &Reference> = obj.references.iter().map(|r| (r.id.as_str(), r)).collect();
    obj.obligations.iter().all(|o| {
        o.boundary_in.iter().chain(&o.boundary_out).all(|rid| {
            let v = leaves[references[rid.as_str()].leaf.as_str()];
            match roots[v.root.as_str()].framing.as_str() {
                MERKLE_FRAMING => scalar_width(&v.layout).is_some(),
                VLLM_FRAMING => uniform_packing(&v.layout).is_some(),
                _ => false,
            }
        })
    })
}

/// `Eval_Verity` on the boundary words, beyond what the crate's `check_relations`
/// (which sees the lowered statement) decides: the sampled `Input` equations
/// `claimed = x[k]`, which the backend checks at opening time (`PositionRef.expected`).
fn input_equations_hold(obj: &Object, values: &[Vec<u64>]) -> bool {
    let subcircuits: HashMap<[u8; 32], &Subcircuit> = obj.subcircuits.iter().map(|s| (s.digest, s)).collect();
    obj.obligations.iter().zip(values).all(|(o, row)| {
        let s = subcircuits[&o.subcircuit];
        let n_in = o.boundary_in.len();
        s.outgoing.iter().enumerate().all(|(m, &j)| match &s.gates[j as usize].input {
            Some((_, value)) => {
                let prescribed = value.iter().fold(0u64, |acc, b| (acc << 8) | *b as u64);
                row.get(n_in + m) == Some(&prescribed)
            }
            None => true,
        })
    })
}

// --- the suite -----------------------------------------------------------------------------

fn hex_string(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn load_all() -> Vec<(String, Json)> {
    let mut files: Vec<_> = std::fs::read_dir(DIR)
        .expect("fixtures/typed-obligation-v0 (frozen vectors; nothing in this repository regenerates them)")
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|e| e == "json"))
        .collect();
    files.sort();
    files
        .into_iter()
        .map(|p| {
            let text = std::fs::read_to_string(&p).unwrap();
            (p.file_name().unwrap().to_string_lossy().into_owned(), serde_json::from_str(&text).unwrap())
        })
        .collect()
}

#[test]
fn every_vector_agrees() {
    let mut counts = BTreeMap::new();
    let mut bump = |what: &str| *counts.entry(what.to_owned()).or_insert(0usize) += 1;
    let vectors = load_all();
    assert!(vectors.len() >= 50, "expected the full suite, found {}", vectors.len());
    for (file, record) in &vectors {
        let name = record["name"].as_str().unwrap();
        let object = &record["object"];

        // 1. canonical bytes and digest
        let mut text = String::new();
        canonical(object, &mut text);
        assert_eq!(text, record["canonical"].as_str().unwrap(), "{name}: canonical JSON");
        let h_o = tagged_sha256(DIGEST_TAG, text.as_bytes());
        assert_eq!(hex_string(&h_o), record["digest"].as_str().unwrap(), "{name}: object digest");
        bump("canonical");

        // 2. the Lean-scope verdict per subcircuit: its lowering is well formed and well typed
        //    (the body validates and every Input gate can be pinned)
        if let (Ok(obj), Some(expected)) = (parse_object(object), record["subcircuits_well_formed"].as_array()) {
            if let Some(set) = GateSet::resolve(&obj.family_id, obj.width) {
                let source_width = set.op_width(set.op("in").expect("every family has `in`"));
                let ours: Vec<bool> = obj
                    .subcircuits
                    .iter()
                    .map(|s| {
                        validate_subcircuit(s, &set).is_ok()
                            && s.gates.iter().all(|g| g.input.as_ref().map_or(true, |(w, _)| *w == source_width))
                    })
                    .collect();
                let theirs: Vec<bool> = expected.iter().map(|b| b.as_bool().unwrap()).collect();
                assert_eq!(ours, theirs, "{name}: subcircuits_well_formed");
                bump("subcircuits checked");
            }
        }

        // 3. verdict and code
        let expected_verdict = record["verdict"].as_str().unwrap();
        let outcome = parse_object(object).and_then(|obj| validate(&obj).map(|set| (obj, set)));
        match (&outcome, expected_verdict) {
            (Err(code), "reject") => {
                assert_eq!(code.name(), record["code"].as_str().unwrap(), "{name}: rejection code");
                bump("rejected");
                continue;
            }
            (Err(code), other) => panic!("{name}: Rust rejects with {code:?}, vector says {other}"),
            (Ok(_), "reject") => panic!(
                "{name}: Rust accepts, vector rejects with {}",
                record["code"].as_str().unwrap()
            ),
            (Ok(_), _) => {}
        }
        let (obj, set) = outcome.unwrap();
        bump("accepted");

        // 4. the lowering (recomputed from the Verity-level object), the real parser,
        //    the real relation check
        let (bytes, description) = lower(&obj);
        assert_eq!(description, record["lowering"], "{name}: lowering description");
        assert_eq!(hex_string(&bytes), record["statement"].as_str().unwrap(), "{name}: statement bytes");
        let h_l = veritor_zk_common::sha256(&bytes);
        assert_eq!(
            hex_string(&h_l),
            record["statement_digest"].as_str().unwrap(),
            "{name}: statement digest"
        );
        bump("lowering");

        // 4b. the binding column (IB): h_O and h_L as recomputed above, the correct prover's
        //     65 bytes, and check_binding's verdict on the recorded public values
        let binding = &record["binding"];
        assert!(binding.is_object(), "{name}: an accepted record carries a binding column");
        assert_eq!(binding["object_digest"].as_str().unwrap(), hex_string(&h_o), "{name}: binding.object_digest");
        assert_eq!(binding["statement_digest"].as_str().unwrap(), hex_string(&h_l), "{name}: binding.statement_digest");
        let correct = bound_public_values(&h_o, &h_l);
        assert_eq!(check_binding(&h_o, &h_l, &correct), Ok(1), "{name}: the correct prover's bytes bind");
        let public_values = hex(binding["public_values"].as_str().unwrap()).unwrap();
        match binding.get("code").and_then(Json::as_str) {
            None => {
                assert_eq!(public_values, correct.to_vec(), "{name}: binding.public_values are the correct prover's");
                bump("bindings accepted");
            }
            Some(code) => {
                let err = check_binding(&h_o, &h_l, &public_values)
                    .expect_err(&format!("{name}: supplied public values must be refused"));
                assert_eq!(err.name(), code, "{name}: binding code");
                assert_ne!(public_values, correct.to_vec(), "{name}: a refused case is not the correct prover's");
                bump("bindings rejected");
            }
        }
        let statement = parse_statement(&bytes).unwrap_or_else(|e| panic!("{name}: {e}"));
        let resolved = gate_set(&statement).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(resolved.digest(), set.digest());

        // 4b. the format-3 column: the same object (its digest was checked above and is the
        //     one `h_O`), positions merged into ranges; the bytes, the digest and the
        //     description are recomputed here, the real v3 parser reads them back, and
        //     the expansion is the format-2 statement
        let (bytes_v3, statement_v3, described_v3) = lower_v3(&statement, &description);
        assert_eq!(described_v3, record["lowered_v3"], "{name}: lowered_v3 description");
        assert_eq!(hex_string(&bytes_v3), record["statement_v3"].as_str().unwrap(), "{name}: statement_v3 bytes");
        assert_eq!(
            hex_string(&veritor_zk_common::sha256(&bytes_v3)),
            record["statement_v3_digest"].as_str().unwrap(),
            "{name}: statement_v3 digest"
        );
        assert_ne!(bytes_v3, bytes, "{name}: the two formats have different bytes");
        let parsed_v3 = parse_statement_v3(&bytes_v3).unwrap_or_else(|e| panic!("{name}: v3 {e}"));
        assert_eq!(parsed_v3, statement_v3, "{name}: v3 parses back");
        assert_eq!(expand_statement(&parsed_v3), statement, "{name}: v3 expands to v2");
        for o in &parsed_v3.obligations {
            for entry in &o.positions {
                if let PositionEntry::Range(r) = entry {
                    assert!(r.count >= 2 && r.stride >= 1, "{name}: the lowering emits ranges of >= 2 words");
                    assert!(parse_leaf_descriptor(&r.descriptor).is_some());
                }
            }
        }
        bump(if parsed_v3.obligations.iter().any(|o| o.positions.iter().any(|e| matches!(e, PositionEntry::Range(_)))) {
            "lowering v3 with ranges"
        } else {
            "lowering v3 without ranges"
        });
        assert_eq!(
            authenticatable(&obj),
            record["authenticatable"].as_bool().unwrap(),
            "{name}: authenticatable"
        );
        if let Some(values) = record.get("values") {
            let decoded: Vec<Vec<u64>> = values
                .as_array()
                .unwrap()
                .iter()
                .map(|row| row.as_array().unwrap().iter().map(|v| v.as_u64().unwrap()).collect())
                .collect();
            let verdict = check_relations(&statement, &decoded, &resolved);
            let accepted = verdict.is_ok() && input_equations_hold(&obj, &decoded);
            let expected = record["relations"].as_str().unwrap();
            assert_eq!(accepted, expected == "accept", "{name}: relations ({verdict:?})");
            bump(if accepted { "relations accepted" } else { "relations rejected" });
        }

        // 5. the real guest pipeline on a witness: format 1 (frame-v3 openings) or
        //    format 3 (whole packed leaves under the serving side's framing)
        if let Some(witness_hex) = record.get("witness").and_then(Json::as_str) {
            let witness = parse_any_witness(&hex(witness_hex).unwrap()).unwrap();
            let verdict = check_any(&statement, &witness);
            let expected = record["witness_verdict"].as_str().unwrap();
            assert_eq!(
                verdict.is_ok(),
                expected == "accept",
                "{name}: witness ({verdict:?} vs {expected})"
            );
            if let Some(code) = expected.strip_prefix("reject:") {
                // the Python reference's code and the guest's error agree on the phase
                let err = verdict.clone().unwrap_err();
                let phase_ok = match code {
                    "INVALID_OPENING" => matches!(err, veritor_zk_common::CheckError::Opening { .. }),
                    "RELATION_REJECTED" => matches!(err, veritor_zk_common::CheckError::Relation { .. }),
                    "PUBLIC_IO_MISMATCH" => matches!(err, veritor_zk_common::CheckError::PublicInput { .. }),
                    _ => true,
                };
                assert!(phase_ok, "{name}: witness rejected in another phase ({err:?} vs {code})");
            }
            // the format-3 statement on the same witness: the same verdict, the same error
            // variant (a format-3 statement takes a packed witness only)
            if let veritor_zk_common::AnyWitness::Packed(packed) = &witness {
                let ranged = check_batch_ranged(&parsed_v3, packed);
                match (&verdict, &ranged) {
                    (Ok(()), Ok(())) => {}
                    (Err(a), Err(b)) => assert_eq!(
                        std::mem::discriminant(a),
                        std::mem::discriminant(b),
                        "{name}: v3 rejects in another phase ({a:?} vs {b:?})"
                    ),
                    _ => panic!("{name}: v2 {verdict:?} but v3 {ranged:?}"),
                }
                bump("packed witness checked under v3");
            }
            bump(match witness {
                veritor_zk_common::AnyWitness::Packed(_) => "packed witness checked",
                _ => "witness checked",
            });
        }
        let _ = file;
    }
    eprintln!("typed-obligation/v0 vectors: {} files; {counts:?}", vectors.len());
}

#[test]
fn canonical_string_escaping_matches_python() {
    let mut out = String::new();
    canonical_string("a\"b\\c\n\t\u{1}\u{7f}é", &mut out);
    assert_eq!(out, "\"a\\\"b\\\\c\\n\\t\\u0001\u{7f}é\"");
    let mut out = String::new();
    canonical(&serde_json::json!({"b": [1, {"z": null, "a": true}], "a": "x"}), &mut out);
    assert_eq!(out, "{\"a\":\"x\",\"b\":[1,{\"a\":true,\"z\":null}]}");
}
